function UIMazeShopEventMysteriousNode:Refresh(data, type, clickCb)
    if not data then
        return
    end
    self._clickCb = clickCb

    local go = self.item:Find("goodGo")
    if not go then
        if IsNull(self.loader) then
            self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSaleGoods.prefab", nil, true)
        end
        if self.loader.IsSuccess then
            go = CfUtils.InstantiateGo(self.loader.ResultObject, self.item)
            go.name = "goodGo"
        end
    end

    local scr = CfUtils.GetLuaScr(go, "Game.Behaviours.CommonShopSaleGoodNode")
    if scr then
        scr:RefeshSelf(data, type)
    end

    if checkNumber(data.num) <= 0 then
        KTool.SetActive(self.mask, true)
    else
        KTool.SetActive(self.mask, false)
    end

    KTool.SetActive(self.controller.gameObject, true)
end

function UIMazeShopEventMysteriousNode:OnSelect()
    if self._clickCb then
        self._clickCb()
    end
end

function UIMazeShopEventMysteriousNode:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release(true)
        self.loader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeShopEventMysteriousNode
